scenario("a fork changes what lands and keeps everything that decides whether it should", () =>
  runEffect(
    Effect.gen(function* () {
      const fs = yield* FileSystem.FileSystem;
      const fork = `${rig.root}/fork`;
      yield* fs.makeDirectory(fork, { recursive: true });
      for (const name of ["renovate.workflow.ts", "renovate.gitlab.md", "renovate.github.md"]) {
        yield* fs.copyFile(`${ROOT}workflows/${name}`, `${fork}/${name}`);
      }
      yield* fs.copyFile(`${fixtures}/landing.workflow.ts`, `${fork}/landing.workflow.ts`);
      const bin = yield* renovatable();
      yield* rig.queueOutputs([
        TRACKED,
        PACKAGE,
        MERGED,
        RELEASED,
        RECORDED,
        TRACKED,
        PACKAGE,
        MERGED,
        { verdict: "clean", version: "deploy-7", tagged: false },
        RECORDED,
      ]);
      yield* ran({
        entry: shipped("renovate"),
        runId: "r-shipped",
        input: {},
        host: withoutHelle,
      });

      const result = yield* ran({
        entry: `${fork}/landing.workflow.ts`,
        runId: "r-fork",
        input: {},
        host: withoutHelle,
      });
      yield* bin.restore();

      expect(said(result)).toBe("REN-1: renovated deploy-7; production carries it");
      for (const step of ["track", "assess"]) {
        expect(byRun(yield* asked("r-fork", step))).toBe(byRun(yield* asked("r-shipped", step)));
      }
      const merging = yield* asked("r-fork", "merge");
      expect(merging).toContain("Every relevant merge request ends with exactly one outcome");
      expect(merging).toContain("merge fast-forward only");
      expect(yield* asked("r-fork", "release")).toContain("Nothing is tagged here");
      expect(yield* asked("r-fork", "release")).not.toContain("Tag annotated");
    }),
  ),
);

const byRun = (prompt: string) => pipe(prompt, Str.replaceAll(/r-(fork|shipped)/g, "<run>"));

const RELEASING = {
  gitlab: {
    remote: "git@gitlab.example.com:group/app.git",
    url: "https://gitlab.example.com/group/app",
    mr: `https://${PROJECT.gitlab}/-/merge_requests/30`,
    target: `mr:${PROJECT.gitlab}!30`,
  },
  github: {
    remote: "git@github.com:owner/repo.git",
    url: "https://github.com/owner/repo",
    mr: `https://${PROJECT.github}/pull/30`,
    target: `mr:${PROJECT.github}#30`,
  },
} as const;

const APP_ASSESSED = {
  verdict: "clean",
  is_package: false,
  kind_evidence: "a stage and a production environment",
  stage_jobs: { merge_request: [], tag: ["deploy-stage"] },
};

const PACKAGED = {
  verdict: "clean",
  is_package: true,
  kind_evidence: "a publish job on tags, and no deploy",
};
const TAGGED = { verdict: "clean", tag: "v1.2.0", version: "1.2.0" };

const readyMr: (name: MrForge, head: string, merged: string, over?: Partial<FakeMr>) => FakeMr = (
  name,
  head,
  merged,
  over = {},
) => ({
  project: PROJECT[name],
  iid: "30",
  state: "open",
  head,
  mergedSha: merged,
  sourceBranch: "feature",
  targetBranch: "main",
  checks: [{ name: "build", state: "passed" }],
  ...(name === "gitlab"
    ? { approvers: ["alice"], required: 1 }
    : {
        reviews: [{ id: 1, author: "alice", state: "APPROVED", at: "2026-10-20T10:00:00Z" }],
      }),
  ...over,
});

const STILL_RUNNING = {
  checks: [{ name: "build", state: "running" }],
  mergeable: "running",
} satisfies Partial<FakeMr>;
const PIPELINE_PASSED = {
  checks: [{ name: "build", state: "passed" }],
  mergeable: "yes",
} satisfies Partial<FakeMr>;

const revParse = (ref: string, cwd = rig.projectDir) =>
  exec(["git", "rev-parse", ref], { cwd }).pipe(Effect.map((ran) => Str.trim(ran.stdout)));

const pushedBySomebody = (parent: string, force = false) =>
  Effect.gen(function* () {
    const fs = yield* FileSystem.FileSystem;
    const content = `${rig.root}/pushed-by-somebody`;
    yield* fs.writeFileString(content, `${parent}\n`).pipe(Effect.orDie);
    const cwd = rig.projectDir;
    const blob = Str.trim((yield* exec(["git", "hash-object", "-w", content], { cwd })).stdout);
    const env = { ...process.env, GIT_INDEX_FILE: `${rig.root}/pushed-by-somebody.index` };
    yield* exec(["git", "read-tree", parent], { cwd, env });
    yield* exec(["git", "update-index", "--add", "--cacheinfo", `100644,${blob},pushed.txt`], {
      cwd,
      env,
    });
    const tree = Str.trim((yield* exec(["git", "write-tree"], { cwd, env })).stdout);
    const sha = Str.trim(
      (yield* exec(["git", "commit-tree", tree, "-p", parent, "-m", "pushed by somebody"], {
        cwd,
      })).stdout,
    );
    yield* exec(
      ["git", "push", "-q", ...(force ? ["-f"] : []), "origin", `${sha}:refs/heads/feature`],
      { cwd: rig.projectDir },
    );
    return sha;
  });

const tagRun = (merged: string) => ({ ref: "v1.2.0", sha: merged });
// WARNING: a rebase keeps the tree and changes the parent, so the target must not carry the old head.
const rebasedBySomebody = (parent: string) =>
  Effect.gen(function* () {
    const cwd = rig.projectDir;
    const tree = `${parent}^{tree}`;
    const target = Str.trim(
      (yield* exec(["git", "commit-tree", tree, "-m", "the newer target"], { cwd })).stdout,
    );
    const rebased = Str.trim(
      (yield* exec(["git", "commit-tree", tree, "-p", target, "-m", "rebased onto the target"], {
        cwd,
      })).stdout,
    );
    yield* exec(["git", "push", "-q", "-f", "origin", `${rebased}:refs/heads/feature`], { cwd });
    return rebased;
  });

const tagOnOrigin = (sha: string) =>
  Effect.gen(function* () {
    yield* exec(["git", "tag", "-a", "v1.2.0", "-m", "1.2.0", sha], { cwd: rig.projectDir });
    yield* exec(["git", "push", "-q", "origin", "v1.2.0"], { cwd: rig.projectDir });
  });

const releasable = (name: MrForge, over: Partial<FakeMr> = {}, tagged = true) =>
  Effect.gen(function* () {
    const reviewed = yield* reviewedBranch();
    yield* exec(["git", "commit", "-qm", "the change", "--allow-empty"], { cwd: reviewed });
    yield* exec(["git", "push", "-q", "origin", "feature"], { cwd: reviewed });
    const head = yield* revParse("HEAD", reviewed);
    const base = yield* revParse("HEAD");
    const merged = Str.trim(
      (yield* exec(
        ["git", "commit-tree", `${head}^{tree}`, "-p", base, "-p", head, "-m", "Merge feature"],
        { cwd: rig.projectDir },
      )).stdout,
    );
    yield* exec(["git", "push", "-q", "origin", `${merged}:refs/heads/main`], {
      cwd: rig.projectDir,
    });
    if (tagged) {
      yield* tagOnOrigin(merged);
    }
    yield* exec(["git", "remote", "set-url", "upstream", RELEASING[name].remote], {
      cwd: rig.projectDir,
    });
    const bin = yield* FakeBin.make(`${rig.root}/bin`);
    const model: ForgeModel = {
      installed: true,
      loggedIn: [FORGE_HOST[name]],
      login: "tester",
      mrs: [readyMr(name, head, merged, over)],
      reviewsRequired: { classic: name === "github" ? 1 : 0 },
    };
    const forge = yield* forgeOnPath(bin, name, model);
    const changed = (over: Partial<FakeMr>) =>
      Effect.gen(function* () {
        const now = yield* forge.model();
        yield* forge.set({ ...now, mrs: Arr.map(now.mrs, (one) => ({ ...one, ...over })) });
      });
    return { bin, forge, head, base, merged, reviewed, changed };
  });

const mergingAfter: <E>(before: Effect.Effect<void, E, FileSystem.FileSystem>) => HostOverride = <
  E,
>(
  before: Effect.Effect<void, E, FileSystem.FileSystem>,
) =>
  Layer.effect(Host)(
    Effect.gen(function* () {
      const host = yield* Host;
      const services = yield* Effect.context<PlatformServices>();
      return Host.of({
        ...host,
        merge: (asked) =>
          before.pipe(
            Effect.orDie,
            Effect.provideContext(services),
            Effect.andThen(host.merge(asked)),
          ),
      });
    }),
  );

type Ends = Readonly<Record<string, { succeeded: boolean; failure: string } | null>>;

interface HelleSays {
  readonly said?: ReadonlyArray<string>;
  readonly waits?: Effect.Effect<void>;
  readonly adopts?: true;
  readonly held: Claimed;
}
const claimedFor: Array<{ applications: ReadonlyArray<string>; jobs: ReadonlyArray<string> }> = [];
const refusedBack: Array<ReadonlyArray<string>> = [];

const releaseHost = <E = never>(
  ends: Ends = {},
  whileClaiming: Effect.Effect<void, E, FileSystem.FileSystem | Path.Path> = Effect.void,
  stallAfterReplies = Infinity,
  helle?: () => HelleSays,
  beforeAlignment: Effect.Effect<void, E, FileSystem.FileSystem | Path.Path> = Effect.void,
) =>
  Layer.effect(Host)(
    Effect.gen(function* () {
      const host = yield* Host;
      const services = yield* Effect.context<
        PlatformServices | ForgeHttp | RunRecords | Registered
      >();
      let replies = 0;
      let aligned = false;
      return Host.of({
        ...host,
        evidence: (runId, cwd) =>
          host.evidence(runId, cwd).pipe(
            Effect.tap(() =>
              aligned
                ? Effect.void
                : Effect.sync(() => {
                    aligned = true;
                  }).pipe(
                    Effect.andThen(
                      beforeAlignment.pipe(Effect.orDie, Effect.provideContext(services)),
                    ),
                  ),
            ),
          ),
        reply: (asked) =>
          host
            .reply(asked)
            .pipe(Effect.tap(() => (++replies >= stallAfterReplies ? Effect.never : Effect.void))),
        holders: () => Effect.succeed({ _tag: "Read", projects: [], applications: [], jobs: [] }),
        claim: (options) =>
          helle !== undefined
            ? Effect.gen(function* () {
                claimedFor.push(options.deploys ?? { applications: [], jobs: [] });
                const says = helle();
                if (says.adopts === true && !(yield* options.adopting)) {
                  return yield* new WorkflowError({
                    reason: "the Helle claim on project was already yours and was not taken over",
                  });
                }
                for (const line of says.said ?? []) {
                  yield* options.say(line);
                }
                yield* says.waits ?? Effect.void;
                if ("slugs" in says.held && says.held.slugs.length > 0) {
                  claimed.push(`claim ${options.runId}`);
                }
                return says.held;
              })
            : claimed.lastIndexOf(`claim ${options.runId}`) >
                claimed.lastIndexOf(`release ${options.runId}`)
              ? Effect.succeed({ slugs: ["project"] })
              : options.say("holding the claim").pipe(
                  Effect.tap(() => Effect.sync(() => claimed.push(`claim ${options.runId}`))),
                  Effect.tap(() =>
                    whileClaiming.pipe(Effect.orDie, Effect.provideContext(services)),
                  ),
                  Effect.as({ slugs: ["project"] }),
                ),
        release: (runId) =>
          Effect.sync(() => {
            claimed.push(`release ${runId}`);
            return refusedBack.shift() ?? [];
          }),
        takeOverLanding: (asked) =>
          Effect.gen(function* () {
            const runs = yield* Effect.forEach(Rec.toEntries(ends), ([runId, ended]) =>
              Effect.map(readLanding(runDir(dir, runId)), (landing) => ({
                runId,
                landing,
                ended,
              })),
            );
            const mr = yield* factOf(asked.runId, MERGE_REQUEST);
            if (mr === null) {
              return yield* Effect.die(`${asked.runId} has no merge request`);
            }
            return yield* takeOver({
              runDir: runDir(dir, asked.runId),
              mr: Str.trim(mr),
              runs,
              cwd: asked.cwd,
              run: shell,
            });
          }).pipe(Effect.orDie, Effect.provideContext(services)),
      });
    }),
  );

const driven = <A, E>(
  options: ShippedRun & {
    readonly restarted?: boolean;
    readonly reached?: Deferred.Deferred<void>;
    readonly runsChildren?: boolean | "tags";
  },
  drive: (run: {
    readonly status: Effect.Effect<typeof RunStatus.Type>;
    readonly asked: Effect.Effect<
      ReadonlyArray<{
        decision: string;
        prompt: string;
        options: string;
        answer: string | null;
        shipping?: ShippingGo | null;
      }>
    >;
    readonly answer: (decision: string, value: string) => Effect.Effect<void>;
    readonly taken: (decision: string) => Effect.Effect<boolean>;
    readonly resume: Effect.Effect<void>;
  }) => Effect.Effect<A, E, FileSystem.FileSystem | Path.Path | Records | Store>,
) =>
  session(
    Effect.gen(function* () {
      const childScope = options.runsChildren ? yield* Scope.make() : null;
      if (childScope !== null) {
        runningChildren = {
          context: yield* Effect.context<SessionServices>(),
          scope: childScope,
          tagsOnly: options.runsChildren === "tags",
        };
      }
      const made = yield* loaded(options.entry, options.runId);
      const engine = yield* WorkflowEngine.WorkflowEngine;
      const store = yield* Store;
      const sql = yield* SqlClient.SqlClient;
      const reached = options.reached;
      const answering =
        reached === undefined
          ? engine
          : WorkflowEngine.WorkflowEngine.of({
              ...engine,
              poll: (workflow, id) =>
                Effect.tap(engine.poll(workflow, id), () => Deferred.succeed(reached, undefined)),
              deferredDone: (deferred, done) =>
                Effect.tap(engine.deferredDone(deferred, done), () =>
                  Deferred.succeed(reached, undefined),
                ),
            });
      if (options.restarted !== true) {
        yield* admit({ runId: options.runId, workflow: made.workflow.name, input: options.input });
      }
      const payload = { runId: options.runId, input: options.input };
      return yield* Effect.gen(function* () {
        yield* made.workflow.execute(payload, { discard: true });
        const id = yield* made.workflow.executionId(payload);
        const status = engine
          .poll(made.workflow, id)
          .pipe(Effect.map((got) => pollStatus(got, "")));
        return yield* drive({
          status,
          asked: store.asked(options.runId),
          resume: engine.resume(made.workflow, id),
          answer: (decision, value) =>
            answerDecision(made, { name: decision, executionId: id, value }).pipe(
              Effect.orDie,
              Effect.provideService(WorkflowEngine.WorkflowEngine, answering),
            ),
          taken: (decision) =>
            sql
              .unsafe<{ processed: number }>(
                `SELECT processed FROM cluster_messages WHERE tag = 'deferred' AND payload LIKE '%"name":"${decision}"%'`,
              )
              .pipe(Effect.map(Arr.some((row) => row.processed === 1)), Effect.orDie),
        });
      }).pipe(
        Effect.provide(made.layer),
        Effect.ensuring(childScope === null ? Effect.void : Scope.close(childScope, Exit.void)),
      );
    }),
    options.host,
  );

const answeredEarly = (question: string, over: HostOverride) => {
  const held = Deferred.makeUnsafe<void>();
  const reached = Deferred.makeUnsafe<void>();
  const host: HostOverride = Layer.effect(Host)(
    Effect.gen(function* () {
      const host = yield* Host;
      return Host.of({
        ...host,
        asking: (runId, asked, asker) =>
          host
            .asking(runId, asked, asker)
            .pipe(
              Effect.andThen(
                asked.name === question && !Deferred.isDoneUnsafe(held)
                  ? Deferred.succeed(held, undefined).pipe(Effect.andThen(Deferred.await(reached)))
                  : Effect.void,
              ),
            ),
      });
    }),
  ).pipe(Layer.provide(over));
  return { host, held, reached };
};

const goAsked = (
  asked: Effect.Effect<
    ReadonlyArray<{
      decision: string;
      prompt: string;
      options: string;
      answer: string | null;
      shipping?: ShippingGo | null;
    }>
  >,
  name: string,
) =>
  until(
    () => asked,
    (rows) => Arr.some(rows, (row) => row.decision === name && row.answer === null),
  ).pipe(
    Effect.map((rows) =>
      Option.getOrUndefined(Arr.findFirst(rows, (row) => row.decision === name))!,
    ),
  );

const openAfter = (
  asked: Effect.Effect<ReadonlyArray<{ decision: string; answer: string | null }>>,
  ...answered: ReadonlyArray<string>
) =>
  until(
    () => asked,
    (rows) => Arr.some(rows, (row) => row.answer === null && !answered.includes(row.decision)),
  ).pipe(
    Effect.map((rows) =>
      Arr.map(
        Arr.filter(rows, (row) => row.answer === null && !answered.includes(row.decision)),
        (row) => row.decision,
      ),
    ),
  );

