const agentPush = (
  forge: { readonly holding: (next: ForgeModel) => { path: string; text: string } },
  model: ForgeModel,
  parent: string,
) =>
  Effect.gen(function* () {
    const sha = yield* pushedBySomebody(parent);
    const moved = { ...model, mrs: Arr.map(model.mrs, (one) => ({ ...one, head: sha })) };
    return {
      sha,
      writes: [
        { path: `${rig.projectDir}/.git/refs/heads/feature`, text: `${sha}\n` },
        { path: `${rig.root}/reviewed/pushed.txt`, text: `${parent}\n` },
        forge.holding(moved),
      ],
      sh: `git -C '${rig.root}/reviewed' read-tree ${sha}`,
    };
  });

const ciRepair = (
  forge: { readonly holding: (next: ForgeModel) => { path: string; text: string } },
  model: ForgeModel,
  reviewed: string,
  state: "running" | "failed" = "running",
  jobs?: FakeMr["jobs"],
) => {
  const repaired = forge.holding({
    ...model,
    mrs: Arr.map(model.mrs, (one) => ({
      ...one,
      head: "REPAIRED_HEAD",
      checks: [{ name: "build", state }],
      ...(jobs !== undefined && { jobs }),
    })),
  });
  return {
    writes: [repaired],
    sh: `cd '${reviewed}' && git rev-parse HEAD >> ci-repair.txt && git add ci-repair.txt && git commit -qm repair-ci && git push -q origin HEAD:feature && sed -i "s/REPAIRED_HEAD/$(git rev-parse HEAD)/" '${repaired.path}'`,
    output: { verdict: "clean", fixed: [{ title: "repaired CI" }] },
  };
};

const conflictRepair = (
  forge: { readonly holding: (next: ForgeModel) => { path: string; text: string } },
  model: ForgeModel,
  reviewed: string,
  target = "main",
  stillConflicting = false,
) => {
  const repaired = forge.holding({
    ...model,
    mrs: Arr.map(model.mrs, (one) => ({
      ...one,
      head: "REPAIRED_HEAD",
      mergeable: stillConflicting ? "conflict" : "yes",
      checks: [{ name: "build", state: "passed" }],
      jobs: [
        { name: "static", state: "passed" },
        { name: "test", state: "passed" },
      ],
    })),
  });
  return {
    writes: [repaired],
    sh: `cd '${reviewed}' && test -z "$(git status --porcelain)" && git rev-parse HEAD >> '${rig.root}/repair-heads' && git fetch -q origin && git merge --no-ff --no-edit 'origin/${target}'${stillConflicting ? " && git commit --allow-empty -qm another-repair" : ""} && git push -q origin HEAD:feature && sed -i "s/REPAIRED_HEAD/$(git rev-parse HEAD)/" '${repaired.path}'`,
    output: { verdict: "clean", fixed: [{ title: "merged the target into the source" }] },
  };
};

